INSERT INTO "records" ("id","entity","data","created_date","updated_date","created_by","created_by_id") VALUES ('6ae9ed9f70bc4e8652df7edc','LeadInteraction','{"lead_id":"6ae9e9fa12a09473c8acf8ab","empresa":"Barbearia Black Zone República Aurora","tipo":"whatsapp_enviado","mensagem":"Olá! Tudo bem? 😊\n\nMeu nome é Lúcia, sou representante oficial da TS Digital Influencer.\n\nEncontrei a Barbearia Black Zone República Aurora pelo Google e vi que vocês possuem uma ótima avaliação, com nota 4,8 estrelas e 121 avaliações! Parabéns pelo trabalho! 👏\n\nGostaria de saber se posso te enviar uma apresentação bem rapidinha de uma solução que ajuda barbearias a facilitar o acesso dos clientes às avaliações no Google Maps e ao Instagram, fortalecendo ainda mais sua presença digital.\n\nSe tiver interesse, basta me responder com um \"1\" ou \"Pode enviar\".\n\nCaso não tenha interesse ou não seja o momento, sem problemas! Agradeço pela atenção e desejo muito sucesso à Black Zone! 😊","autor":"Registro manual","detalhe":"Mensagem enviada fora da API e registrada no histórico.","is_sample":false}'::jsonb,'2026-11-03T14:20:15.931000','2026-11-03T14:20:15.931000',NULL,'6ae7617c2831b38d03d681fc') ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
INSERT INTO "records" ("id","entity","data","created_date","updated_date","created_by","created_by_id") VALUES ('6ae762dd91886d9ed0755ef2','Produto','{"nome":"Kit Google + Instagram","slug":"kit-2-placas-nfc","descricao_curta":"Uma placa para a avaliação no Google e um display para o Instagram.","descricao":"Kit completo com duas peças NFC personalizadas: a placa de avaliação no Google e o display neon do Instagram, cada uma com o seu link exclusivo.\n\nPerfeito para quem quer aumentar as avaliações e também ganhar seguidores. Configuramos e testamos os dois links antes da entrega.","preco":99,"preco_antigo":120,"modelo":"acrilico","imagens":["/media/b304a9015_display-instagram-acrilico-neon.png","/media/2a9bce66f_placa-nfc-avaliacao-google.jpg"],"itens_inclusos":["1 placa de avaliação Google","1 display Instagram neon","Chips NFC programados","Teste dos links antes da entrega"],"estoque":20,"prazo_producao":"Produção em até 7 dias úteis","ativo":true,"destaque":false,"is_sample":false}'::jsonb,'2026-11-01T16:03:41.454000','2026-11-02T11:28:46.361000',NULL,'6ae7617c2831b38d03d681fc') ON CONFLICT ("id") DO NOTHING;
