INSERT INTO "records" ("id","entity","data","created_date","updated_date","created_by","created_by_id") VALUES ('6ae762dd91886d9ed0755ef1','Produto','{"nome":"Placa NFC de Balcão com Suporte","slug":"placa-nfc-balcao","descricao_curta":"Placa com suporte de mesa, ideal para balcões, recepções e caixas.","descricao":"Modelo de balcão com suporte removível, pensado para recepções e caixas de atendimento. Mesma tecnologia NFC, com personalização da sua marca.\n\nLinks do Google e do Instagram configurados e testados antes da entrega.","preco":75,"preco_antigo":0,"modelo":"pvc","imagens":["/media/2a9bce66f_placa-nfc-avaliacao-google.jpg"],"itens_inclusos":["Placa + suporte de mesa","Chip NFC programado","Página exclusiva com seus links"],"estoque":30,"prazo_producao":"Produção em até 7 dias úteis","ativo":true,"destaque":false,"is_sample":false}'::jsonb,'2026-11-01T16:03:41.454000','2026-11-02T11:27:17.266000',NULL,'6ae7617c2831b38d03d681fc') ON CONFLICT ("id") DO NOTHING;
